<div class="d-flex justify-content-between flex-wrap gap-3 mb-4"><div><h2 class="h4"><?= ge($import['nome_arquivo']) ?></h2><p class="text-muted mb-0">Importação #<?= (int)$import['id'] ?> · <?= ge($import['status']) ?></p></div><a class="btn btn-light align-self-start" href="/admin/gadsan/importacoes">Voltar às importações</a></div>
<div class="gadsan-stats mb-4"><?php foreach (['total_linhas'=>'Linhas recebidas','total_importados'=>'Novos colaboradores','total_ignorados'=>'Sem novo cadastro','total_inconsistencias'=>'Alertas registrados'] as $key=>$label): ?><div class="card p-3"><span class="text-muted"><?= ge($label) ?></span><strong class="fs-3"><?= (int)$import[$key] ?></strong></div><?php endforeach ?></div>
<details class="card p-3 mb-4"><summary class="fw-semibold">Resumo das inconsistências</summary><ul class="mt-3 mb-0"><?php foreach ($pending as $row): ?><li><?= ge(str_replace('_',' ',$row['tipo_inconsistencia'])) ?>: <?= (int)$row['pendentes'] ?> pendente(s) de <?= (int)$row['total'] ?></li><?php endforeach ?><?php if (!$pending): ?><li>Nenhum alerta registrado.</li><?php endif ?></ul></details>
<div class="card"><div class="card-header"><h3 class="h5 mb-0">Linhas de origem</h3></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Aba / linha</th><th>Resultado</th><th>Colaborador</th><th>Conferência</th></tr></thead><tbody>
<?php foreach ($origins as $row): ?><tr><td><?= ge($row['aba']) ?><small class="d-block">Linha <?= (int)$row['linha'] ?></small></td><td><?= ge(str_replace('_',' ',$row['resultado'])) ?></td><td><?php if ($row['colaborador_id']&&$canView): ?><a href="/admin/gadsan/colaboradores/<?= (int)$row['colaborador_id'] ?>">Cadastro #<?= (int)$row['colaborador_id'] ?></a><?php else: ?>Sem cadastro acessível<?php endif ?></td><td><a href="/admin/gadsan/origens/<?= (int)$row['id'] ?>">Ver origem e alertas</a></td></tr><?php endforeach ?>
<?php if (!$origins): ?><tr><td colspan="4" class="text-muted p-4">Nenhuma linha persistida nesta carga.</td></tr><?php endif ?>
</tbody></table></div></div>
<nav class="d-flex gap-3 mt-3" aria-label="Paginação das origens"><?php if ($page>1): ?><a class="btn btn-light" href="?pagina=<?= $page-1 ?>">Anterior</a><?php endif ?><span class="align-self-center">Página <?= $page ?></span><?php if ($page*25<$total): ?><a class="btn btn-light" href="?pagina=<?= $page+1 ?>">Próxima</a><?php endif ?></nav>
